SELECT 
      [map('elementId', CAST(concat('User:', toString(v0.user_id), '-'), 'Dynamic'), 'labels', CAST(['User'], 'Dynamic'), 'properties', CAST(mapFilter((__k, __v) -> __v IS NOT NULL, map('age', CAST(v0.age, 'Dynamic'), 'city', CAST(v0.city, 'Dynamic'), 'country', CAST(v0.country, 'Dynamic'), 'email', CAST(v0.email_address, 'Dynamic'), 'is_active', CAST(v0.is_active, 'Dynamic'), 'name', CAST(v0.full_name, 'Dynamic'), 'registration_date', CAST(v0.registration_date, 'Dynamic'), 'user_id', CAST(v0.user_id, 'Dynamic'))), 'Dynamic')), map('elementId', CAST(concat('FOLLOWS:', concat(coalesce(replaceAll(replaceAll(replaceAll(toString(v1.follow_id), '\\', '\\\\'), ':', '\\:'), '|', '\\|'), '\\N')), ':', toString(v1.follower_id), '->', toString(v1.followed_id), '-'), 'Dynamic'), 'startNodeElementId', CAST(concat('User:', toString(v1.follower_id), '-'), 'Dynamic'), 'endNodeElementId', CAST(concat('User:', toString(v1.followed_id), '-'), 'Dynamic'), 'type', CAST('FOLLOWS', 'Dynamic'), 'properties', CAST(mapFilter((__k, __v) -> __v IS NOT NULL, map('follow_date', CAST(v1.follow_date, 'Dynamic'))), 'Dynamic')), map('elementId', CAST(concat('User:', toString(v2.user_id), '-'), 'Dynamic'), 'labels', CAST(['User'], 'Dynamic'), 'properties', CAST(mapFilter((__k, __v) -> __v IS NOT NULL, map('age', CAST(v2.age, 'Dynamic'), 'city', CAST(v2.city, 'Dynamic'), 'country', CAST(v2.country, 'Dynamic'), 'email', CAST(v2.email_address, 'Dynamic'), 'is_active', CAST(v2.is_active, 'Dynamic'), 'name', CAST(v2.full_name, 'Dynamic'), 'registration_date', CAST(v2.registration_date, 'Dynamic'), 'user_id', CAST(v2.user_id, 'Dynamic'))), 'Dynamic'))] AS "p"
FROM test_integration.users_test AS v0
JOIN test_integration.user_follows_test AS v1 ON v1.follower_id = v0.user_id
JOIN test_integration.users_test AS v2 ON v1.followed_id = v2.user_id
LIMIT 5
